(()=>{if(window.matchMedia('(prefers-reduced-motion: reduce)').matches||!('IntersectionObserver' in window))return;const seen=new WeakSet();const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('arrive');entry.target.addEventListener('animationend',()=>entry.target.classList.remove('arrive'),{once:true});observer.unobserve(entry.target)}})},{threshold:.08});function watch(){document.querySelectorAll('.hero-copy,.collage,.section-heading,.project-card,.matchbox,.play-grid article,.letter,.card,.place-group').forEach((el,i)=>{if(seen.has(el))return;seen.add(el);el.style.setProperty('--arrival-delay',(i%3)*65+'ms');observer.observe(el)})}watch();const projects=document.getElementById('projects');if(projects)new MutationObserver(watch).observe(projects,{childList:true});})();
